SET default_transaction_read_only = on;
\copy (WITH days AS (SELECT DISTINCT ticker, alert_date AS d FROM mi_live_trades WHERE account_mode = 'live' AND signal_type = 'magna53' AND filled_at IS NOT NULL AND (filled_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-08-16' UNION SELECT DISTINCT ticker, (filled_at AT TIME ZONE 'America/New_York')::date AS d FROM mi_live_trades WHERE account_mode = 'live' AND signal_type = 'magna53' AND filled_at IS NOT NULL AND (filled_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-08-16') SELECT b.ticker, to_char(b.bar_time AT TIME ZONE 'America/New_York', 'YYYY-MM-DD HH24:MI') AS bar_et, b.open, b.high, b.low, b.close, b.volume FROM days x JOIN mi_intraday_bars b ON b.ticker = x.ticker AND b.bar_time >= (x.d + TIME '09:30') AT TIME ZONE 'America/New_York' AND b.bar_time < (x.d + TIME '16:00') AT TIME ZONE 'America/New_York' ORDER BY b.ticker, b.bar_time) TO STDOUT WITH CSV HEADER
